import { ObservedProbe } from 'app/features/observe/observed-probe/model/observed-probe.model';
import { ObservedProbeRepository } from 'app/features/observe/observed-probe/repository/observed-probe-repository.service';
import { ConfirmAction } from 'app/shared/toolkit/action/confirm-action';
import { Component, inject } from '@angular/core';

@Component({ selector: 'observed-probe-view-disable-action', standalone: false, template: '' })
export class ObservedProbeViewDisableActionComponent extends ConfirmAction<ObservedProbe> {
  readonly name = 'disable';
  protected readonly scope = 'observe/observed-probe';
  protected readonly repository = inject(ObservedProbeRepository);

  protected override appliesTo(items: ObservedProbe[]) {
    return items.every((item) => !!item.enabled) && true;
  }
  protected execute([item]: ObservedProbe[]) {
    return this.repository.disable(item.uid);
  }
}
